mapper.select:
select a.contract_code, a.org_id, a.client_code, a.business_code, a.lessee_margin_balance, a.supplier_margin_balance, a.payable_margin_balance, a.other_margin_balance, ec.contract_name , ec.lease_date_start , ec.lease_date_end , ec.business_name , ec.currency_type , ec.client_name from eg_contract_balance a inner join ( select contract_code, max(update_time) update_time from eg_contract_balance where period_code = #{param.periodCode} and del_flag = '0' and contract_code is not null and client_code is not null and (lessee_margin_balance != 0 or supplier_margin_balance != 0 or payable_margin_balance != 0 or other_margin_balance !=0) group by contract_code ) b on a.update_time = b.update_time and a.contract_code = b.contract_code left join eg_contract ec on a.contract_code = ec.contract_code where a.period_code = #{param.periodCode} and a.del_flag = '0' and a.contract_code is not null and a.client_code is not null and (a.lessee_margin_balance != 0 or a.supplier_margin_balance != 0 or payable_margin_balance != 0 or other_margin_balance !=0)
and a.business_code in
#{item}
and a.id in
#{item}
and a.contract_code not in
#{item}
and a.org_id = #{param.orgId}
and a.org_id in
#{item}
and a.org_id not in
#{item}

select t.org_id, t.business_code, t.contract_code, t.client_code, sum(coalesce(payable_other_cost_estimate_balance, 0)) as payable_other_cost_estimate_balance, sum(coalesce(payable_agency_estimate_balance, 0)) as payable_agency_estimate_balance, sum(coalesce(payable_vehicle_estimate_balance, 0)) as payable_vehicle_estimate_balance, sum(coalesce(payable_band_cost_estimate_balance, 0)) as payable_band_cost_estimate_balance, sum(coalesce(payable_pledge_estimate_balance, 0)) as payable_pledge_estimate_balance, sum(coalesce(payable_unpledge_estimate_balance, 0)) as payable_unpledge_estimate_balance, sum(coalesce(payable_device_estimate_balance, 0)) as payable_device_estimate_balance, sum(coalesce(receivable_outtax_balance, 0)) as receivable_outtax_balance, sum(coalesce(unrealized_revenue_balance, 0)) as unrealized_revenue_balance, sum(coalesce(receive_sum_outtax_balance, 0)) as receive_sum_outtax_balance, sum(coalesce(receive_unrealized_revenue_balance, 0)) as receive_unrealized_revenue_balance, sum(coalesce(payable_other_estimate_balance, 0)) as payable_other_estimate_balance, sum(coalesce(receivable_rent_balance, 0)) as receivable_rent_balance, sum(coalesce(receivable_residual_value_balance, 0)) as receivable_residual_value_balance, sum(coalesce(payable_device_balance, 0)) as payable_device_balance, sum(coalesce(payable_other_balance, 0)) as payable_other_balance from (select * from eg_contract_balance_latest order by org_id,business_code,contract_code,client_code) t where 1 = 1 and (t.payable_other_cost_estimate_balance!=0 or t.payable_agency_estimate_balance!=0 or t.payable_vehicle_estimate_balance!=0 or t.payable_band_cost_estimate_balance!=0 or t.payable_pledge_estimate_balance!=0 or t.payable_unpledge_estimate_balance!=0 or t.payable_device_estimate_balance !=0 or t.receivable_outtax_balance !=0 or t.unrealized_revenue_balance !=0 or t.receive_sum_outtax_balance !=0 or t.receive_unrealized_revenue_balance !=0 or t.payable_other_estimate_balance !=0 )
and t.period_code = #{param.periodCode}
and t.org_id in
#{item}
and to_char(t.voucher_date,'YYYY-MM-DD') = to_char(#{param.voucherDate},'YYYY-MM-DD')
group by t.org_id, t.business_code, t.contract_code, t.client_code

with balance as ( select cb.* from eg_contract_balance_latest cb where 1 = 1 and cb.id in ( select max(x.id) from eg_contract_balance_latest x where 1 = 1 and x.del_flag = '0'
and x.period_code = #{param.periodCode}
and x.org_id = #{param.orgId}
and x.contract_code in
#{item}
and x.org_id in
#{item}
and x.client_code in
#{item}
group by x.org_id, x.contract_code) union all select * from eg_contract_balance_temp ecbt where 1 = 1 and ecbt.id in ( select max(x.id) from eg_contract_balance_temp x where 1 = 1 and x.del_flag = '0'
and x.period_code = #{param.periodCode}
and x.org_id = #{param.orgId}
and x.scene_code = #{param.sceneCodeForTemp}
and x.contract_code in
#{item}
and x.org_id in
#{item}
and x.client_code in
#{item}
group by x.org_id, x.contract_code) )
select * from balance where 1 = 1 and id in ( select id from ( select id, row_number() over (partition by org_id, contract_code order by create_time desc) as rn from balance ) sub where rn = 1 )
and period_code = #{param.periodCode}

select contract_code, org_id, client_code, receivable_rent_balance, receivable_residual_value_balance, receivable_outtax_balance, unrealized_revenue_balance, lessee_margin_balance, payable_agency_estimate_balance, payable_vehicle_estimate_balance, payable_band_cost_estimate_balance, payable_pledge_estimate_balance, payable_unpledge_estimate_balance, payable_other_cost_estimate_balance, depreciation_reserves_balance from eg_contract_balance where 1 = 1 and id in ( select max(id) from eg_contract_balance t where 1 = 1
and t.contract_code in
#{item}
and t.org_id in
#{item}
and t.client_code in
#{item}
and to_char(t.voucher_date,'YYYY-MM-DD') <= to_char(#{param.voucherDate},'YYYY-MM-DD')
and to_char(t.voucher_date,'YYYY-MM-DD') >= to_char(#{param.voucherDateStart},'YYYY-MM-DD')
)

select ecb.business_date, ecb.voucher_date, ecb.period_code, ecb.scene_code, es.scene_name, sum(ecb.receivable_rent_balance) as receivable_rent_balance, sum(ecb.receivable_rent_amount) as receivable_rent_amount, sum(ecb.unrealized_revenue_balance) as unrealized_revenue_balance, sum(ecb.unrealized_revenue_amount) as unrealized_revenue_amount, sum(ecb.lease_revenue_balance) as lease_revenue_balance, sum(ecb.lease_revenue_amount) as lease_revenue_amount, sum(ecb.depreciation_reserves_balance) as depreciation_reserves_balance, sum(ecb.depreciation_reserves_amount) as depreciation_reserves_amount, sum(ecb.receivable_outtax_balance) as receivable_outtax_balance, sum(ecb.receivable_outtax_amount) as receivable_outtax_amount, sum(ecb.receivable_service_outtax_balance) as receivable_service_outtax_balance, sum(ecb.receivable_service_outtax_amount) as receivable_service_outtax_amount, sum(ecb.payable_device_balance + ecb.payable_device_estimate_balance) as payable_device_balances, sum(ecb.payable_device_estimate_amount + ecb.payable_device_amount) as payable_device_amounts, sum(ecb.lessee_margin_balance) as lessee_margin_balance, sum(ecb.lessee_margin_amount) as lessee_margin_amount from eg_contract_balance ecb left join eg_scene es on ecb.scene_code = es.scene_code and es.del_flag ='0' where 1=1
and ecb.contract_code = #{param.contractCode}
and ecb.org_id = #{param.orgId}
group by ecb.business_date, ecb.voucher_date, ecb.period_code, ecb.scene_code, es.scene_name order by ecb.voucher_date desc

select contract_code, org_id, sum(receivable_rent_balance) receivable_rent_balance, sum(receivable_residual_value_balance) receivable_residual_value_balance, sum(receivable_outtax_balance) receivable_outtax_balance, sum(unrealized_revenue_balance) unrealized_revenue_balance, sum(lessee_margin_balance) lessee_margin_balance, sum(receive_cost_balance) receive_cost_balance, sum(equipment_depreciation_reserves_balance) equipment_depreciation_reserves_balance from eg_contract_balance ecb where 1=1
and ecb.org_id = #{param.orgId}
and ecb.org_id in
#{item}
and ecb.contract_code in
#{item}
and ecb.id in( select max(id) from eg_contract_balance where 1=1
and org_id = #{param.orgId}
and org_id in
#{item}
and voucher_date <= #{param.voucherDate}
and contract_code in
#{item}
group by org_id, contract_code, client_code ) group by org_id, contract_code

select sum(receivable_outtax_amount)         as receivable_outtax_amount,
       sum(receivable_service_outtax_amount) as receivable_service_outtax_amount
from eg_contract_balance
where period_code = #{periodCode}
  and scene_code = 'KJFP'
  and org_id = #{orgId}
  and contract_code = #{contractCode}
  and voucher_date >= #{voucherDate}

select * from (select id, org_id, client_code, scene_code, contract_code, voucher_date, receivable_rent_balance, receivable_residual_value_balance, receivable_outtax_balance, unrealized_revenue_balance, lessee_margin_balance, payable_agency_estimate_balance, payable_vehicle_estimate_balance, payable_band_cost_estimate_balance, payable_pledge_estimate_balance, payable_unpledge_estimate_balance, payable_other_cost_estimate_balance, depreciation_reserves_balance, lease_revenue6_amount, lease_revenue_amount, depreciation_reserves_amount, receivable_unconfirm_receipt_amount, collect_claims_balance, receivable_service_outtax_amount, receivable_outtax_amount, row_number() over (partition by contract_code order by id desc) as rn from eg_contract_balance x where x.del_flag = '0' and x.contract_code in
#{contractCode}
and x.scene_code in
#{sceneCode}
and x.org_id = #{param.orgId}
and to_char(x.voucher_date,'YYYY-MM-DD') <= to_char(#{param.voucherDateEnd},'YYYY-MM-DD')
and to_char(x.voucher_date,'YYYY-MM-DD') >= to_char(#{param.voucherDateStart},'YYYY-MM-DD')
order by id desc ) t where t.rn = 1

select org_id as org_id, contract_code as contract_code, scene_code as scene_code, sum(lease_revenue6_amount) as lease_revenue6_amount, sum(lease_revenue_amount) as lease_revenue_amount, sum(depreciation_reserves_amount) as depreciation_reserves_amount, sum(receivable_unconfirm_receipt_amount) as receivable_unconfirm_receipt_amount, sum(receivable_service_outtax_amount) as receivable_service_outtax_amount, sum(receivable_outtax_amount) as receivable_outtax_amount, sum(receivable_outtax_debt_restructure_amount) as receivable_outtax_debt_restructure_amount, sum(interest_other_long_payables_amount) as interest_other_long_payables_amount, sum(other_payable_spv_amount) as other_payable_spv_amount, sum(collect_payment_amount) as collect_payment_amount, sum(receive_sum_outtax_amount) as receive_sum_outtax_amount, sum(receivable_outtax_investment_property_amount) as receivable_outtax_investment_property_amount, sum(other_business_income_amount) as other_business_income_amount from eg_contract_balance where del_flag = '0' and voucher_date >= #{voucherDate} and period_code >= #{periodCode} and scene_code in #{sceneCode} and (
org_id = #{orgId} and contract_code in
#{contractCode}
) GROUP BY org_id, contract_code, scene_code
